                | Some(SyntaxStruct::ConditionalConstraintSyntax)
                | Some(SyntaxStruct::LoopConstraintSyntax)
                | Some(SyntaxStruct::DisableConstraintSyntax)
                | Some(SyntaxStruct::SolveBeforeConstraintSyntax)
